export function PropertyPanel({
  title = "{{title}}",
  density = "{{density}}",
  accent = "{{accent}}",
  collapsible = {{collapsible}},
}) {
  const compact = density === "compact";
  const rows = [["Opacity", "100%"], ["Blend mode", "Normal"], ["Corner radius", "8"]];
  const body = rows.map(([k, v]) => (
    <label key={k} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: compact ? "3px 0" : "6px 0", gap: 8, fontSize: compact ? 12 : 13 }}>
      <span style={{ color: "#24143099" }}>{k}</span>
      <input type="text" value={v} readOnly style={{ width: 80, boxSizing: "border-box", border: "1px solid #24143022", borderRadius: 5, padding: "3px 6px", textAlign: "right", background: "#fff", color: "#241430" }} />
    </label>
  ));
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", background: "#FAF7F2", padding: 12, maxWidth: 260, boxSizing: "border-box", border: "1px solid #24143018", borderRadius: 8 }}>
      {collapsible ? (
        <details open>
          <summary style={{ marginBottom: 8, fontWeight: 700, cursor: "pointer", color: accent }}>{title}</summary>
          {body}
        </details>
      ) : (
        <>
          <h4 style={{ margin: "0 0 8px", fontWeight: 700, color: accent }}>{title}</h4>
          {body}
        </>
      )}
    </div>
  );
}
